    location_text: job.remote ? 'Remote' : (job.location || 'Unknown'),
    salary: job.salary_min ? job.salary_min + '-' + job.salary_max : (job.salary || ''),
    description: job.description || job.summary || '',
    posted_date: job.created_at || '',
    tags: Array.isArray(job.skills) ? job.skills.map(s => s.value || s).join(',') : '',
    job_id: 'otta_' + (job.id || job.slug || String(Math.random()).slice(2))
  }
}));

const existingItems = (() => { try { return $('Read Existing Job URLs').all(); } catch(e) { return []; } })();
const existingUrls = new Set(existingItems.map(i => (i.json.job_url || '')).filter(Boolean));
const existingKeys = new Set(existingItems.map(i => ((i.json.company || '') + '_' + (i.json.job_title || '')).toLowerCase()).filter(k => k !== '_'));
const seen = new Set();
const result = [];
for (const item of $input.all()) {
  if (!item.json.job_title || item.json._empty) continue;
  const url = item.json.job_url || '';
  const key = ((item.json.company || '') + '_' + (item.json.job_title || '')).toLowerCase();
  if (url && existingUrls.has(url)) continue;
  if (key !== '_' && existingKeys.has(key)) continue;
  if (url && seen.has(url)) continue;
  if (!url && seen.has(key)) continue;
  seen.add(url || key);
  result.push(item);
}
return result;

const rejectTerms = [
  'us only','usa only','united states only','us-based only','based in the us',
  'canada only','uk only','united kingdom only','eu only','europe only',
  'australia only','new zealand only','must be based in','must live in',
  'must be authorized to work','authorized to work in the','work permit required',
  'local work permit','right to work','onsite','on-site','on site',
  'office required','in-office','in office','hybrid','partially remote',
  'remote within us','remote in us','remote in the us','remote within canada',
  'remote within uk','remote within eu','fixed us hours','fixed est hours',
  'fixed pst hours','fixed cet hours','fixed gmt hours','must relocate',
  'relocation required'
];
const strongKeepTerms = [
  'worldwide remote','work from anywhere','global remote','anywhere in the world',
  'hire via deel','hires via deel','deel.com','hires via remote.com','remote.com',
  'hires via oyster','oyster.com','eor supported','employer of record',
  'international contractors welcome','accepts contractors globally',
  'anywhere','all timezones','all time zones'
];
return $input.all().map(item => {
  const text = [
    item.json.description || '',
    item.json.location_text || '',
    item.json.tags || '',
    item.json.job_title || ''
  ].join(' ').toLowerCase();
  const hasStrongKeep = strongKeepTerms.some(t => text.includes(t));
  const hasReject = rejectTerms.some(t => text.includes(t));
  let hard_filter_result = 'passed';
  let hard_filter_reason = '';
  if (hasReject && !hasStrongKeep) {
    hard_filter_result = 'rejected';
    hard_filter_reason = rejectTerms.find(t => text.includes(t)) || 'Country/onsite restriction';
  }
  return { json: { ...item.json, hard_filter_result, hard_filter_reason } };
});

const job = $input.first().json;
const prompt = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.

Do not pass the job only because it says "remote."

REJECT if:
- The job requires the worker to live in the US, Canada, UK, EU, Europe, Australia, or any specific country outside Taiwan
- The job requires local work authorization outside Taiwan
- The job is hybrid, onsite, or remote within one country only
- The job requires fixed working hours that would force Jerry to work midnight or early morning in Taiwan (UTC+8)

KEEP if ANY of these is true:
- The job says worldwide remote, work from anywhere, or global remote
- The job says APAC remote
- The job allows international contractors
- The job accepts people based anywhere
- The company hires through EOR, Deel, Remote.com, Oyster, or B2B contractor agreement

Return JSON only — no other text:
{
  "taiwan_eligible": "yes/no/unclear",
  "reason": "one short sentence",
  "location_risk": "low/medium/high",
  "timezone_risk": "low/medium/high",
  "contractor_possible": "yes/no/unclear",
  "decision": "keep/reject/manual_check"
}

Job Title: ${job.job_title || ''}
Company: ${job.company || ''}
Location: ${job.location_text || ''}
Tags: ${job.tags || ''}
Job Post:
${(job.description || '').slice(0, 3000)}`;
const requestBody = {
  model: 'gpt-4o-mini',
  messages: [{ role: 'user', content: prompt }],
  response_format: { type: 'json_object' },
  temperature: 0.1,
  max_tokens: 400
};
return [{ json: { ...job, _ai_request_body: JSON.stringify(requestBody) } }];

const item = $input.first();
const job = item.json;

// Parse AI response
let ai = { taiwan_eligible: 'unclear', reason: 'No AI response', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
try {
  const content = job?.choices?.[0]?.message?.content;
  if (content) ai = { ...ai, ...JSON.parse(content) };
} catch(e) {
  ai.reason = 'Parse error: ' + e.message;
}

// Async level detection
const text = ((job.description || '') + ' ' + (job.job_title || '')).toLowerCase();
const asyncHigh = ['async','asynchronous','async-first','async first','flexible hours','flexible schedule','low meeting','no meetings','work across time zones','work across timezones'];
const asyncMed  = ['distributed team','remote-first','remote first','global team','across time zones','flexible working'];
const asyncLow  = ['strict 9-5','strict 9 to 5','fixed us hours','fixed est','fixed pst','fixed cet','daily live calls required','must overlap full business day','real-time collaboration required','synchronous'];
const asyncLevel = asyncLow.some(t => text.includes(t)) ? 'low' : asyncHigh.some(t => text.includes(t)) ? 'high' : asyncMed.some(t => text.includes(t)) ? 'medium' : 'medium';

// Role fit
const title = (job.job_title || '').toLowerCase();
const roleHighTerms = ['data analyst','data scientist','bi analyst','business intelligence','marketing analyst','performance marketing','growth analyst','ai marketing','ai automation','ai workflow','martech','marketing data','analytics engineer','reporting analyst','marketing science'];
const roleMedTerms = ['analytics','digital marketing','growth hacker','seo specialist','ppc analyst','paid media','paid search','product analyst','content strategist','creative strategist'];
const isHigh = roleHighTerms.some(t => title.includes(t) || text.includes(t));
const isMed  = !isHigh && roleMedTerms.some(t => title.includes(t) || text.includes(t));
const roleCategory = isHigh ? (roleHighTerms.find(t => title.includes(t)) || 'data/ai/marketing') : (isMed ? 'adjacent' : 'other');

// Salary parsing
const salaryStr = (job.salary || '').replace(/,/g,'');
const nums = (salaryStr.match(/\d{3,6}/g) || []).map(Number).filter(n => n >= 100);
const maxSalary = nums.length ? Math.max(...nums) : 0;

// Score calculation
let score = 0;
const te = (ai.taiwan_eligible || 'unclear').toLowerCase();
const lr = (ai.location_risk || 'medium').toLowerCase();
const tz = (ai.timezone_risk || 'medium').toLowerCase();

// Taiwan eligibility (0-40)
if (te === 'yes' && lr === 'low')       score += 40;
else if (te === 'yes')                   score += 35;
else if (lr === 'low')                   score += 30;
else if (te === 'unclear' && lr !== 'high') score += 20;

// Async fit (0-25)
if (asyncLevel === 'high')   score += 25;
else if (asyncLevel === 'medium') score += 15;

// Role fit (0-25)
if (isHigh) score += 25;
else if (isMed) score += 15;

// Salary (0-25)
if (maxSalary >= 5000) score += 25;
else if (maxSalary >= 3000) score += 15;
else if (maxSalary > 0 || salaryStr.trim()) score += 10;

// One-sentence rule check
const passesRule = te !== 'no' && lr !== 'high' && tz !== 'high' && asyncLevel !== 'low';

// Decision
let decision = 'reject';
if (!passesRule || ai.decision === 'reject') {
  decision = 'reject';
} else if (score >= 85 && te === 'yes') {
  decision = 'apply';
} else if (score >= 70) {
  decision = te === 'unclear' ? 'manual_check' : 'keep';
} else {
  decision = 'reject';
}

const whyParts = [];
if (te === 'yes' && lr === 'low') whyParts.push('Taiwan eligible (low risk)');
else if (te === 'yes') whyParts.push('Taiwan eligible');
else if (te === 'unclear') whyParts.push('Taiwan eligibility unclear — needs review');
if (asyncLevel === 'high') whyParts.push('fully async');
if (isHigh) whyParts.push('strong role match');
if (maxSalary >= 5000) whyParts.push('$5k+/mo salary');
else if (maxSalary >= 3000) whyParts.push('$3k+/mo salary');

return [{
  json: {
    date_found: $now.toFormat('yyyy-MM-dd'),
    job_title: job.job_title || '',
    company: job.company || '',
    job_url: job.job_url || '',
    source: job.source || '',
    location_text: job.location_text || '',
    salary: job.salary || '',
    description: job.description || '',
    posted_date: job.posted_date || '',
    tags: job.tags || '',
    job_id: job.job_id || '',
    score: score,
    taiwan_eligible: te,
    taiwan_reason: ai.reason || '',
    location_risk: lr,
    timezone_risk: tz,
    contractor_possible: ai.contractor_possible || 'unclear',
    async_level: asyncLevel,
    role_category: roleCategory,
    why_good_fit: whyParts.join(', ') || 'Review manually',
    decision: decision,
    application_status: decision === 'apply' ? 'ready_to_apply' : '',
    notes: ''
  }
}];

const item = $input.first();
const job = item.json;
let coverLetter = '';
try {
  coverLetter = job?.choices?.[0]?.message?.content || '';
} catch(e) { coverLetter = 'Cover letter generation failed.'; }
return [{ json: { ...job, cover_letter: coverLetter } }];

const jobs = $input.all().map(i => i.json).filter(j => j.job_title);
const date = $now.setZone('Asia/Taipei').toFormat('cccc, LLLL d yyyy');
const kept = jobs.filter(j => j.decision !== 'reject').sort((a,b) => (Number(b.score)||0) - (Number(a.score)||0));
const topJobs = kept.slice(0, 10);
const manual = kept.filter(j => j.decision === 'manual_check');
const rejected = jobs.filter(j => j.decision === 'reject');
const rejectedUS = rejected.filter(j => /us only|united states|usa only/i.test(j.taiwan_reason||j.notes||'')).length;
const rejectedEU = rejected.filter(j => /eu only|europe only/i.test(j.taiwan_reason||j.notes||'')).length;
const rejectedHybrid = rejected.filter(j => /hybrid|onsite/i.test(j.taiwan_reason||j.notes||'')).length;
const rejectedTZ = rejected.filter(j => j.timezone_risk === 'high').length;

let html = `<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;max-width:680px;margin:0 auto;padding:24px;color:#222">`;
html += `<h1 style="color:#1a1a2e;border-bottom:3px solid #0066cc;padding-bottom:12px">Daily Taiwan Eligible Async Remote Jobs</h1>`;
html += `<p style="color:#555;margin-top:4px">${date} &bull; Taiwan time (UTC+8)</p>`;
html += `<p style="font-size:18px"><strong>${kept.length}</strong> jobs passed &bull; <strong>${rejected.length}</strong> rejected &bull; <strong>${manual.length}</strong> manual check</p>`;
html += `<hr style="border:1px solid #eee">`;

if (topJobs.length === 0) {
  html += `<p style="color:#666;font-size:16px">No qualifying jobs found today. The filters held. Check back tomorrow.</p>`;
} else {
  html += `<h2 style="color:#0066cc">Top Jobs Today</h2>`;
  topJobs.forEach((j, i) => {
    const scoreColor = Number(j.score) >= 85 ? '#00aa44' : Number(j.score) >= 70 ? '#0066cc' : '#888';
    const badge = Number(j.score) >= 85 ? ' ⭐ APPLY NOW' : '';
    html += `<div style="border:1px solid #ddd;border-radius:10px;padding:18px;margin:18px 0;border-left:5px solid ${scoreColor}">`;
    html += `<h3 style="margin:0 0 8px 0;color:#111">${i+1}. ${j.job_title||'Untitled'}${badge}</h3>`;
    html += `<table style="width:100%;font-size:14px"><tr><td style="padding:3px 8px 3px 0;color:#555;width:40%"><strong>Company</strong></td><td>${j.company||'Unknown'}</td></tr>`;
    html += `<tr><td style="padding:3px 8px 3px 0;color:#555"><strong>Score</strong></td><td style="color:${scoreColor};font-weight:bold">${j.score}/100</td></tr>`;
    html += `<tr><td style="padding:3px 8px 3px 0;color:#555"><strong>Taiwan Eligible</strong></td><td>${j.taiwan_eligible||'unclear'}</td></tr>`;
    html += `<tr><td style="padding:3px 8px 3px 0;color:#555"><strong>Reason</strong></td><td>${j.taiwan_reason||'N/A'}</td></tr>`;
    html += `<tr><td style="padding:3px 8px 3px 0;color:#555"><strong>Async Level</strong></td><td>${j.async_level||'medium'}</td></tr>`;
    html += `<tr><td style="padding:3px 8px 3px 0;color:#555"><strong>Timezone Risk</strong></td><td>${j.timezone_risk||'medium'}</td></tr>`;
    html += `<tr><td style="padding:3px 8px 3px 0;color:#555"><strong>Salary</strong></td><td>${j.salary||'Not listed'}</td></tr>`;
    html += `<tr><td style="padding:3px 8px 3px 0;color:#555"><strong>Why it fits</strong></td><td>${j.why_good_fit||'N/A'}</td></tr></table>`;
    html += `<p style="margin-top:12px;margin-bottom:0"><a href="${j.job_url||'#'}" style="background:#0066cc;color:#fff;padding:8px 18px;border-radius:6px;text-decoration:none;font-weight:bold">Apply Now →</a></p>`;
    html += `</div>`;
  });
}

if (manual.length > 0) {
  html += `<h2 style="color:#e07b00">Manual Check Required (${manual.length})</h2><p style="color:#666">Taiwan eligibility is unclear but score is high. Review these manually.</p>`;
  manual.forEach(j => {
    html += `<div style="border:1px solid #f0c060;border-radius:6px;padding:12px;margin:8px 0;background:#fffbf0">`;
    html += `<strong><a href="${j.job_url||'#'}" style="color:#333">${j.job_title}</a></strong> @ ${j.company} &bull; Score: ${j.score}`;
    html += `<br><small style="color:#777">${j.taiwan_reason||''}</small></div>`;
  });
}

html += `<h2 style="color:#cc2200">Rejected Summary</h2>`;
html += `<ul style="font-size:14px;color:#555">`;
html += `<li>US Only: <strong>${rejectedUS}</strong></li>`;
html += `<li>EU Only: <strong>${rejectedEU}</strong></li>`;
html += `<li>Hybrid / Onsite: <strong>${rejectedHybrid}</strong></li>`;
html += `<li>High Timezone Risk: <strong>${rejectedTZ}</strong></li>`;
html += `<li>Total Rejected: <strong>${rejected.length}</strong></li>`;
html += `</ul>`;
html += `<hr style="border:1px solid #eee;margin-top:32px">`;
html += `<p style="color:#aaa;font-size:12px">Jerry's one rule: <em>I can do this job while living in Taiwan, without moving, without foreign work authorization, and without destroying my sleep schedule.</em></p>`;
html += `</body></html>`;

return [{ json: { digest_html: html, top_count: topJobs.length, kept_count: kept.length, rejected_count: rejected.length, manual_count: manual.length } }];
